#include <vector>
#include <map>

using namespace std;

typedef unsigned long long big_int;

class stringx;

class string_buf
{
protected:
  friend class stringx;
  friend inline bool operator<( const stringx& lhs, const stringx& rhs );

  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

public:
  int compare(const string_buf& b) const;
};

class stringx
{
  friend class string_buf;

  protected:
    char *chars;
    string_buf *my_buf;

  public:
    stringx(const stringx&);
    ~stringx();
    friend inline bool operator<( const stringx& lhs, const stringx& rhs );
};

inline bool operator<( const stringx& lhs, const stringx& rhs )
{
  return (lhs.my_buf->compare(*rhs.my_buf) == 1);
}

class singleton
{
};

typedef short anim_id_t;

class anim_id_manager : public singleton
{
 public:
  typedef vector<stringx> label_list;
  typedef map< stringx, anim_id_t > label_map_t;

 private:
  label_list labels;
  label_map_t label_map;
  stringx NO_ID_label;

 public:
  anim_id_t anim_id( const stringx& _label );
};

anim_id_t anim_id_manager::anim_id( const stringx& _label )
{
  label_map_t::iterator lm = label_map.find(_label);
  if (lm==label_map.end())
  {
    labels.push_back( _label );
    label_map.insert(label_map_t::value_type(_label,labels.size() - 1));
    return labels.size() - 1;
  }
  else
    return (*lm).second;
}
